            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1]  # Gratis
            else:
                dp[i][j] = 1 + min(
                    dp[i-1][j],    # Eliminar
                    dp[i][j-1],    # Insertar
                    dp[i-1][j-1],  # Reemplazar
                )

    return dp[m][n]

