# DP: Longest Increasing Subsequence (LIS)

def lis(nums: list[int]) -> int:
    """Longitud de la subsecuencia creciente más larga — O(n²)."""
    if not nums:
        return 0
    dp = [1] * len(nums)
    for i in range(1, len(nums)):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

